        }

        // fallback
        if (!ok) {
          input.focus();
          input.select();
          input.setSelectionRange(0, text.length);
          try {
            ok = document.execCommand("copy");
          } catch (_) {
            ok = false;
          }
          input.blur();
        }

        if (ok) setState(btn, true);

        window.setTimeout(() => {
          setState(btn, false);
          btn.dataset.copyBusy = "0";
        }, 1500);
      });
    }

