.hero__uptitle-item{display:flex;align-items:center;gap:9px;font-size:16px;font-weight:600;color:#2C2C2C}
.hero__uptitle-ico{display:inline-flex}
.hero__title{font-size:44px;line-height:1.15;font-weight:800;margin:0 0 18px}
.hero__text{font-size:18px;line-height:1.65;color:#4A4A4A;max-width:760px;margin:0 0 30px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;border:1px solid transparent;border-radius:999px;padding:18px 46px;font-size:20px;font-weight:700;cursor:pointer;transition:transform .12s ease, box-shadow .12s ease, background .12s ease;text-decoration:none}
.btn--primary{background:#3A944A;color:#fff;box-shadow:0 12px 28px rgba(58,148,74,.32)}
.btn--primary:hover{background:#317F3E;transform:translateY(-1px)}
.btn:active{transform:translateY(1px)}
.btn:disabled{opacity:.45;cursor:not-allowed;transform:none}
/* ---------- modal ---------- */
.disc-modal{position:fixed;inset:0;z-index:100001;display:none}
.disc-modal.is-open{display:block}
.disc-modal__overlay{position:absolute;inset:0;background:rgba(0,0,0,.55)}
.disc-modal__dialog{position:relative;width:min(1240px,calc(100% - 64px));margin:56px auto;background:#fff;border-radius:22px;box-shadow:0 40px 120px rgba(0,0,0,.28);overflow:hidden;max-height:90vh;display:flex;flex-direction:column}
.disc-modal__close{position:absolute;top:24px;right:24px;z-index:3;width:48px;height:48px;border:0;background:transparent;font-size:0;cursor:pointer;opacity:.55}
.disc-modal__close::before,.disc-modal__close::after{content:"";position:absolute;left:50%;top:50%;width:30px;height:2px;background:#7A7A7A;transform-origin:center}
.disc-modal__close::before{transform:translate(-50%,-50%) rotate(45deg)}
.disc-modal__close::after{transform:translate(-50%,-50%) rotate(-45deg)}
.disc-modal__close:hover{opacity:1}
.disc-modal__head{padding:42px 56px 14px;text-align:center;flex-shrink:0}
.disc-modal__title{color:#0F0F0F;font-size:30px;font-weight:800;line-height:1.2;margin:0}
.disc-modal__sub{margin-top:12px;color:#272727;font-size:17px}
.disc-modal__lead{margin-top:14px;color:#409C54;font-size:19px;font-weight:600}
.disc-modal__tabs{padding:12px 32px 8px;display:flex;gap:8px;justify-content:flex-start;overflow-x:auto;flex-shrink:0;scrollbar-width:thin}
.disc-modal__tabs::-webkit-scrollbar{height:5px}
.disc-modal__tabs::-webkit-scrollbar-thumb{background:#C8D6EA;border-radius:99px}
.disc-tab{flex:0 0 auto;border:0;border-radius:10px;padding:12px 18px;font-size:17px;font-weight:600;line-height:1;cursor:pointer;background:#EAF2FA;color:#2C2C2C;white-space:nowrap}
.disc-tab.is-active{background:#1F5BD6;color:#fff}
.disc-modal__body{padding:8px 32px 40px;flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch}
.disc-pane{display:none}
.disc-pane.is-active{display:block}
.disc-grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:14px}
.disc-card{border:1px solid rgba(0,0,0,.18);border-radius:10px;overflow:hidden;background:#fff}
.disc-card__title{padding:14px 18px;font-size:21px;font-weight:800;color:#1C1C1C}
.disc-card__foot{padding:14px 18px;font-size:20px;font-weight:800;color:#1C1C1C}
.disc-list{list-style:none;margin:0 16px;padding:0;border:1px solid rgba(0,0,0,.12)}
.disc-item{position:relative;padding:16px 46px 16px 16px;font-size:18px;color:#2C2C2C;border-top:1px solid rgba(0,0,0,.12);background:#fff;user-select:none}
.disc-item:first-child{border-top:0}
.disc-handle{position:absolute;right:12px;top:50%;transform:translateY(-50%);width:28px;height:28px;display:flex;align-items:center;justify-content:center;cursor:grab;user-select:none;touch-action:none;opacity:.75}
.disc-handle:hover{opacity:1}
.disc-handle svg{display:block;width:16px;height:16px;pointer-events:none}
.disc-item.is-dragging{opacity:.5;z-index:9999;background:#fff;box-shadow:0 14px 34px rgba(0,0,0,.22);border-radius:8px}
.disc-item.is-dragging .disc-handle{cursor:grabbing}
.disc-item.is-over{outline:2px dashed rgba(31,91,214,.45);outline-offset:-6px}
.disc-item.is-preview{outline:2px dashed rgba(31,91,214,.55);outline-offset:-5px}
body.is-dragging{cursor:grabbing}
body.is-dragging *{cursor:grabbing !important}
.disc-progress{position:sticky;bottom:64px;margin:24px 0 0;height:18px;border-radius:999px;background:rgba(0,0,0,.08);overflow:hidden;z-index:2}
.disc-progress__bar{height:100%;width:0;border-radius:999px;background:#6FE28A;transition:width .2s ease}
.disc-actions{position:sticky;bottom:0;margin:14px 0 0;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0 4px;background:#fff;z-index:2}
.disc-btn{border:1px solid rgba(0,0,0,.22);border-radius:999px;padding:14px 38px;font-size:19px;font-weight:600;cursor:pointer;background:#fff;color:#1C1C1C;max-width:100%}
.disc-btn--primary{border-color:transparent;background:#3A944A;color:#fff}
.disc-btn--primary:hover{background:#317F3E}
.disc-btn:disabled{opacity:.45;cursor:not-allowed}
/* ---------- result ---------- */
.result-pane{display:none}
.result-pane.is-active{display:block}
.result{margin-top:16px;background:#fff;border:1px solid rgba(0,0,0,.14);border-radius:14px;padding:34px 38px}
.result__title{font-size:26px;font-weight:800;margin:0 0 8px}
.result__desc{margin:0 0 26px;color:#4A4A4A;font-size:16px;line-height:1.6;max-width:820px}
.result__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:26px}
.result__cell{border-radius:12px;padding:20px 18px;color:#fff;text-align:center}
.result__cell--d{background:#D64545}
.result__cell--i{background:#E8A11B}
.result__cell--s{background:#3A944A}
.result__cell--c{background:#1F5BD6}
.result__cell-name{display:block;font-size:15px;font-weight:600;opacity:.92;margin-bottom:10px}
.result__cell-score{display:block;font-size:34px;font-weight:800;line-height:1}
.result__hint{display:flex;gap:12px;align-items:flex-start;background:#F4F8FD;border:1px solid #D8E4F5;border-radius:12px;padding:16px 18px;font-size:15px;line-height:1.55;color:#2C2C2C}
.result__hint svg{flex-shrink:0;margin-top:2px}
.result__restart{margin-top:26px}
/* ---------- responsive ---------- */
@media (max-width: 1000px){
  .disc-modal__dialog{width:calc(100% - 16px);margin:8px auto;max-height:96vh}
  .disc-modal__head{padding:26px 18px 10px}
  .disc-modal__body{padding:6px 14px 30px}
  .disc-grid3{grid-template-columns:1fr;gap:14px}
  .disc-progress{bottom:62px}
  .result__grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width: 1100px){
  .disc-modal__dialog{width:calc(100% - 20px);margin:10px auto}
}
@media (max-width: 560px){
  .hero{padding:44px 0 40px}
  .hero__title{font-size:30px}
  .hero__text{font-size:16px}
  .btn{padding:15px 30px;font-size:17px}
  .disc-actions{flex-direction:column;align-items:stretch}
  .disc-btn{width:100%}
  .disc-progress{bottom:158px}
  .result{padding:22px 18px}
  .result__grid{grid-template-columns:1fr 1fr}
}
