  var resultPane = qs("#resultPane");
  var btnPrev = qs("[data-disc-prev]", wizard);
  var btnNext = qs("[data-disc-next]", wizard);
  var btnFinish = qs("[data-disc-finish]", wizard);
  var progressEl = qs("#discProgress", wizard);

  var step = 0;
  var finished = false;
  var lastFocus = null;

  function scrollLock(on) {
    document.documentElement.classList.toggle("no-scroll", on);
    document.body.classList.toggle("no-scroll", on);
  }

  function openWizard() {
    lastFocus = document.activeElement;
    wizard.classList.add("is-open");
    wizard.setAttribute("aria-hidden", "false");
    scrollLock(true);
    body.scrollTop = 0;
    render();
    wizard.querySelector(".disc-modal__close").focus({ preventScroll: true });
  }

  function closeWizard() {
    wizard.classList.remove("is-open");
    wizard.setAttribute("aria-hidden", "true");
    scrollLock(false);
    if (lastFocus && typeof lastFocus.focus === "function") lastFocus.focus({ preventScroll: true });
  }

  function isMobileUI() {
    return (window.matchMedia && window.matchMedia("(max-width: 767px)").matches) ||
      (window.matchMedia && window.matchMedia("(pointer: coarse)").matches && window.matchMedia && window.matchMedia("(max-width: 1024px)").matches);
  }

  function centerActiveTab(behavior) {
    if (!isMobileUI()) return;
    var scroller = wizard.querySelector(".disc-modal__tabs");
    if (!scroller || !scroller.scrollWidth) return;
    var activeTab = null;
    tabs.forEach(function (t) { if (Number(t.dataset.stepBtn) === step) activeTab = t; });
    if (!activeTab) return;
    var containerRect = scroller.getBoundingClientRect();
    var tabRect = activeTab.getBoundingClientRect();
    var tabCenterX = (tabRect.left - containerRect.left) + tabRect.width / 2;
    var targetLeft = scroller.scrollLeft + tabCenterX - scroller.clientWidth / 2;
    var maxLeft = Math.max(0, scroller.scrollWidth - scroller.clientWidth);
    var clamped = Math.min(Math.max(0, targetLeft), maxLeft);
    if (Math.abs(scroller.scrollLeft - clamped) < 2) return;
    scroller.scrollTo({ left: clamped, behavior: behavior || "smooth" });
  }

  function render() {
    tabs.forEach(function (t) {
      var is = Number(t.dataset.stepBtn) === step && !finished;
      t.classList.toggle("is-active", is);
      t.setAttribute("aria-selected", is ? "true" : "false");
    });
    panes.forEach(function (p) { p.classList.toggle("is-active", Number(p.dataset.stepPane) === step && !finished); });
    if (resultPane) resultPane.classList.toggle("is-active", finished);
    if (btnPrev) btnPrev.disabled = step === 0;
    if (btnNext) btnNext.hidden = step === 7 || finished;
    if (btnFinish) btnFinish.hidden = !(step === 7 && !finished);
    if (progressEl) {
      progressEl.style.width = finished ? "100%" : (((step + 1) / 8) * 100) + "%";
    }
    if (isMobileUI()) requestAnimationFrame(function () { centerActiveTab("smooth"); });
  }

  function setStep(n) {
    if (finished) return;
    step = Math.max(0, Math.min(7, n));
    body.scrollTo({ top: 0, behavior: "smooth" });
    render();
  }

  function setFinished() {
    finished = true;
    render();
    body.scrollTo({ top: 0, behavior: "smooth" });
  }

  // ---------- collect + score ----------
  function collectPayload() {
    var payload = [];
    qsa(".disc-list", wizard).forEach(function (ul, listIndex) {
      qsa("li", ul).forEach(function (li, idx) {
        payload.push({ list: listIndex, pos: idx, type: li.getAttribute("data-type") });
      });
    });
    return payload;
  }

  function scoreOf(payload) {
    var maj = [], min = [];
    payload.forEach(function (x) {
      if (x.pos === 0) maj.push(x.type);
      if (x.pos === 3) min.push(x.type);
    });
    var count = function (arr, ch) { return arr.reduce(function (a, v) { return a + (v === ch ? 1 : 0); }, 0); };
    return {
      d: count(maj, "d") - count(min, "d"),
      i: count(maj, "i") - count(min, "i"),
      s: count(maj, "s") - count(min, "s"),
      c: count(maj, "c") - count(min, "c")
    };
  }

