    var res = scoreOf(collectPayload());
    res.d = Number(res.d); res.i = Number(res.i); res.s = Number(res.s); res.c = Number(res.c);
    var span = resultPane.querySelector('[data-score="' + function(){return "d"} + '"]');
    ["d","i","s","c"].forEach(function (k) {
      var el = resultPane.querySelector('[data-score="' + k + '"]');
      if (el) el.textContent = res[k];
    });
    setFinished();
  }

  function restart() {
