    step = 0;
    // сброс порядка: вернуть исходный порядок (как в HTML) — просто перестроим списки
    // исходный порядок неизвестен после перемещений, но для копии достаточно начать заново с текущим порядком
    resultPane.querySelectorAll(".result__cell-score").forEach(function (el) { el.textContent = "0"; });
