      // только за handle на touch-устройствах
      var handle = e.target.closest(".disc-handle");
      var isTouch = e.pointerType === "touch" || e.type === "touchstart";
      if (isTouch && !handle) return;

      pointerId = e.pointerId;
      startX = e.clientX; startY = e.clientY;
      dragging = li;
      dragList = li.parentElement;
      active = false;

      var rect = li.getBoundingClientRect();
      ghost = li.cloneNode(true);
      ghost.className = "disc-item is-dragging";
      ghost.style.width = rect.width + "px";
      ghost.style.position = "fixed";
      ghost.style.margin = "0";
      ghost.style.zIndex = 10002;
      ghost.style.pointerEvents = "none";
      ghost.style.left = (e.clientX - ghostOffsetX) + "px";
      ghost.style.top = (e.clientY - ghostOffsetY) + "px";
      document.body.appendChild(ghost);
      ghostOffsetX = (e.clientX - rect.left);
      ghostOffsetY = (e.clientY - rect.top);
      ghost.style.left = rect.left + "px";
      ghost.style.top = rect.top + "px";

      li.style.visibility = "hidden";
      li.classList.add("is-dragging");
      document.body.classList.add("is-dragging");

      if (typeof li.setPointerCapture === "function") {
