    qsa(".disc-item", container).forEach(function (child) {
      if (child === dragging) return;
      var box = child.getBoundingClientRect();
      var offset = y - box.top - box.height / 2;
      if (offset < 0 && offset > closest.offset) closest = { offset: offset, element: child };
    });
    return closest.element;
  }

  function onMove(e) {
    if (!dragging) return;
    if (!active) {
      if (Math.hypot(e.clientX - startX, e.clientY - startY) < 5) return;
      active = true;
    }
    e.preventDefault();
    if (ghost) {
      ghost.style.left = (e.clientX + ghost._ox) + "px";
      ghost.style.top = (e.clientY + ghost._oy) + "px";
    }
    var after = getAfterElement(dragList, e.clientY);
    if (after == null) {
      if (dragging !== dragList.lastElementChild) dragList.appendChild(dragging);
    } else {
      dragList.insertBefore(dragging, after);
    }
  }

  function onUp() {
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
    if (!dragging) return;
    var d = dragging;
    if (active) {
      wasDrag = true;
      setTimeout(function () { wasDrag = false; }, 0);
    }
    if (ghost && ghost.parentNode) ghost.parentNode.removeChild(ghost);
    d.style.visibility = "";
    d.classList.remove("is-dragging");
    document.body.classList.remove("is-dragging");
    dragging = null;
    ghost = null;
    active = false;
  }

  function wireList(ul) {
    ul.addEventListener("pointerdown", function (e) {
      if (e.button !== undefined && e.button !== 0) return;
      if (finished) return;
      var li = e.target.closest(".disc-item");
      if (!li) return;
      var handle = e.target.closest(".disc-handle");
      var isTouch = (e.pointerType === "touch") || (e.type === "touchstart");
      if (isTouch && !handle) return;

      startX = e.clientX; startY = e.clientY;
      dragging = li;
      dragList = li.parentElement;
      active = false;

      var rect = li.getBoundingClientRect();
      ghost = li.cloneNode(true);
      ghost.classList.remove("is-dragging");
      ghost.className = "disc-ghost";
      ghost.style.width = rect.width + "px";
      ghost._ox = 0; ghost._oy = 0;
      ghost.style.left = rect.left + "px";
      ghost.style.top = rect.top + "px";
      document.body.appendChild(ghost);
      // смещение так, чтобы ghost совпадал с курсором
      ghost._ox = rect.left - e.clientX;
      ghost._oy = rect.top - e.clientY;
      ghost.style.left = e.clientX + ghost._ox + "px";
      ghost.style.top = e.clientY + ghost._oy + "px";

      window.addEventListener("pointermove", onMove, { passive: false });
      window.addEventListener("pointerup", onUp, { passive: true });
      window.addEventListener("pointercancel", onUp, { passive: true });
    });
  }

  qsa(".disc-list", wizard).forEach(function (ul) {
    ul.style.touchAction = "pan-y";
    wireList(ul);
  });

  // ---------- wiring ----------
  qs("[data-disc-open]").addEventListener("click", function (e) { e.preventDefault(); openWizard(); });
  qsa("[data-disc-close]", wizard).forEach(function (x) {
    x.addEventListener("click", function (e) { e.preventDefault(); closeWizard(); });
  });
  document.addEventListener("keydown", function (e) {
    if (e.key !== "Escape") return;
    if (wizard.classList.contains("is-open")) closeWizard();
  });
  tabs.forEach(function (t) { t.addEventListener("click", function () { setStep(Number(t.dataset.stepBtn)); }); });
  if (btnPrev) btnPrev.addEventListener("click", function () { if (!wasDrag) setStep(step - 1); });
  if (btnNext) btnNext.addEventListener("click", function () { if (!wasDrag) setStep(step + 1); });
  if (btnFinish) btnFinish.addEventListener("click", finishTest);
  qs("#restartBtn").addEventListener("click", restart);

  render();
})();
</script>
</body>
</html>
